viewof selected_cancer = {
  const keys = Object.keys(r_heatmaps);
  let selected = "All Human Cancers";

  // UPDATE: Added sticky positioning, a max-height relative to the viewport, and auto vertical scrolling
  const container = html`&lt;div style="
    display: flex; 
    flex-direction: column; 
    gap: 6px; 
    position: sticky; 
    top: 20px; 
    max-height: calc(100vh - 40px); 
    overflow-y: auto; 
    padding-right: 8px;
  "&gt;&lt;/div&gt;`;

  function render() {
    container.replaceChildren(...keys.map(key =&gt; {
      const isSelected = key === selected;
      const btn = html`&lt;button style="
        text-align: left;
        padding: 8px 12px;
        border: 1px solid ${isSelected ? '#007bff' : '#d1d5db'};
        background: ${isSelected ? '#007bff' : '#f9fafb'};
        color: ${isSelected ? '#fff' : '#1f2937'};
        border-radius: 6px;
        cursor: pointer;
        font-weight: ${isSelected ? 'bold' : 'normal'};
        font-size: 0.95em;
        transition: background 0.15s, border-color 0.15s;
        width: 100%;
      "&gt;${key}&lt;/button&gt;`;

      btn.onmouseover = () =&gt; {
        if (!isSelected) btn.style.background = '#f3f4f6';
      };
      btn.onmouseout = () =&gt; {
        if (!isSelected) btn.style.background = '#f9fafb';
      };

      btn.onclick = () =&gt; {
        selected = key;
        container.value = key;
        container.dispatchEvent(new CustomEvent("input"));
        render();
      };
      return btn;
    }));
  }

  container.value = selected;
  render();
  return container;
}








